index += 1
results = []

for _ in range(T):
    n, x = int(data[index]), int(data[index + 1])
    index += 2
    s = data[index]
    index += 1

    balance = 0
    balance_count = {0: 1}
    total_zeros = s.count('0')
    total_ones = n - total_zeros
    delta = total_zeros - total_ones

    infinite = False
    count = 0

    for char in s:
        if char == '0':
            balance += 1
        else:
            balance -= 1

        if delta == 0:
            if balance == x:
                infinite = True
                break
        else:
            if (x - balance) % delta == 0 and (x - balance) // delta >= 0:
                count += 1

    if infinite:
        results.append(-1)
    else:
        results.append(count)

for result in results:
    print(result)

