import sys
input = sys.stdin.read
data = input().split()

t = int(data[0])
data = data[1:]

results = []
for i in range(t):
    n, x = map(int, data[i*2].split())
    s = data[i*2+1]

    balance = s.count('0') - s.count('1')
    total_zeros = s.count('0') * (n // len(s))
    remaining = s[:n % len(s)]

    prefix_count = 0
    if balance == 0:
        if x == 0:
            prefix_count = -1
        else:
            prefix_count = total_zeros
    else:
        if (x - balance) % balance == 0 and (x - balance) // balance >= 0:
            prefix_count = total_zeros
            if remaining.count('0') == 0:
                prefix_count += 1
    results.append(prefix_count)

for result in results:
    print(result)

